/* @lc app=leetcode id=3493 lang=kotlin */
class Solution { fun numberOfComponents(properties: Array<IntArray>, k: Int): Int = properties.map { p -> p.fold(0L to 0L) { (a, b), v -> if (v < 64) (a or (1L shl v)) to b else a to (b or (1L shl (v - 64))) } }.let { sets -> IntArray(properties.size) { it }.also { p -> (0 until properties.size).flatMap { i -> (i + 1 until properties.size).map { j -> i to j } }.filter { (i, j) -> java.lang.Long.bitCount(sets[i].first and sets[j].first) + java.lang.Long.bitCount(sets[i].second and sets[j].second) >= k }.forEach { (i, j) -> generateSequence(i) { p[it].takeIf { r -> r != it } }.last().let { ri -> generateSequence(j) { p[it].takeIf { r -> r != it } }.last().also { rj -> if (ri != rj) p[ri] = rj } } } }.count { generateSequence(it) { r -> p[r].takeIf { r2 -> r2 != r } }.last() == it } } }